#include <bits/stdc++.h>

using namespace std;

const int MOD = 1000000007;
const int MAXN = 1 << 20;

int qpow(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (1LL * res * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

const int M = 21;

int n;
int f_arr[MAXN], g_arr[MAXN];
int p[M][M];

int idx[2][MAXN];
int rev[MAXN];
int match[M];
int adj[M][M];

void process(int *f, vector<int> left, vector<int> right, vector<int> subgraph, int *idx) {
    vector<pair<int, int>> edges;
    for (auto x : left) {
        for (auto y : right) {
            edges.emplace_back(x, y);
        }
    }

    for (int mask = 0; mask < (1 << (int)edges.size()); ++mask) {
        int prob = 1;
        for (int i = 0; i < (int)edges.size(); ++i) {
            if (mask & (1 << i)) {
                prob = (1LL * prob * p[edges[i].first][edges[i].second]) % MOD;
                adj[edges[i].first][edges[i].second] = 1;
            } else {
                prob = (1LL * prob * (MOD + 1 - p[edges[i].first][edges[i].second])) % MOD;
                adj[edges[i].first][edges[i].second] = 0;
            }
        }
        for (auto g : subgraph) {
            vector<int> perm, indices;
            for (auto x : left) perm.push_back(x);
            for (int i = 0; i < n; ++i) if (g & (1 << i)) indices.push_back(i + n);
            bool found = false;
            do {
                bool valid = true;
                for (int i = 0; i < (int)perm.size(); ++i) {
                    if (!adj[perm[i]][indices[i]]) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    found = true;
                    break;
                }
            } while (next_permutation(indices.begin(), indices.end()));
            if (found) {
                int mask_idx = idx[g];
                rev[mask] |= (1 << mask_idx);
            }
        }
        f[0] = (f[0] + prob) % MOD;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> p[i][j + n];
            p[i][j + n] = (1LL * p[i][j + n] * qpow(100, MOD - 2)) % MOD;
        }
    }

    if (n == 1) {
        cout << p[0][1] << "\n";
        return 0;
    }

    int sizeA = n / 2;
    int sizeB = n - sizeA;

    int countA = 0, countB = 0;
    vector<int> subsetA, subsetB;
    for (int mask = 0; mask < (1 << n); ++mask) {
        if (__builtin_popcount(mask) == sizeA) {
            idx[0][mask] = countA++;
            subsetA.push_back(mask);
        }
        if (__builtin_popcount(mask) == sizeB) {
            idx[1][mask] = countB++;
            subsetB.push_back(mask);
        }
    }

    for (int i = 0; i < (int)subsetB.size(); ++i) {
        int mask = subsetB[i];
        for (int big_mask = 0; big_mask < (1 << countB); ++big_mask) {
            if (big_mask & (1 << i))
                rev[big_mask] |= (1 << idx[0][(1 << n) - 1 - mask]);
        }
    }

    vector<int> left1, left2, right_nodes;
    for (int i = n; i < 2 * n; ++i) {
        right_nodes.push_back(i);
    }
    for (int i = 0; i < sizeA; ++i) left1.push_back(i);
    for (int i = sizeA; i < n; ++i) left2.push_back(i);

    process(f_arr, left1, right_nodes, subsetA, idx[0]);
    process(g_arr, left2, right_nodes, subsetB, idx[1]);

    for (int i = 0; i < countA; ++i) {
        for (int mask = 0; mask < (1 << countA); ++mask) {
            if (mask & (1 << i))
                f_arr[mask] = (f_arr[mask] + f_arr[mask ^ (1 << i)]) % MOD;
        }
    }

    long long total = 0;
    for (int mask = 1; mask < (1 << countB); ++mask) {
        int w = (1 - f_arr[(1 << countA) - 1 - rev[mask]] + MOD) % MOD;
        total = (total + 1LL * w * g_arr[mask]) % MOD;
    }

    cout << total << "\n";

    return 0;
}
